    return Auth()

def _build_auth(self, auth: AuthTypes | None) -> Auth | None:
    if auth is None:
        return None
    elif isinstance(auth, tuple):
        return BasicAuth(username=auth[0], password=[REDACTED]
    elif isinstance(auth, Auth):
        return auth
    elif callable(auth):
        return FunctionAuth(func=auth)
    else:
        raise TypeError(f'Invalid "auth" argument: {auth!r}')

def _set_timeout(self, request: Request) -> None:
    if "timeout" not in request.extensions:
        timeout = (
            self.timeout
            if isinstance(self.timeout, UseClientDefault)
            else Timeout(self.timeout)
        )
        request.extensions = dict(**request.extensions, timeout=timeout.as_dict())

def sync_auth_flow(
    self, request: Request
) -> typing.Generator[Request, Response, None]:
    """
    Execute the authentication flow synchronously.

    By default, this defers to `.auth_flow()`. You should override this method
    when the authentication scheme does I/O and/or uses concurrency primitives.
    """
    if self.requires_request_body:
        request.read()

    flow = self.auth_flow(request)
    request = next(flow)

    while True:
        response = yield request
        if self.requires_response_body:
            response.read()

        try:
            request = flow.send(response)
        except StopIteration:
            break

@field_validator("levels")
@classmethod
def unique_levels(cls, levels: list[str]) -> list[str]:
    if any(not level.strip() or level != level.strip() for level in levels):
        raise ValueError("levels must not have surrounding whitespace")
    if len(set(levels)) != len(levels):
        raise ValueError("score levels must be distinct")
    return levels

async def decide(self, question: Question, policy: Policy | None = None) -> Decision:
    question = question_adapter.validate_python(question.model_dump())
    policy = Policy.model_validate((policy or self.policy).model_dump())
    started = perf_counter()
    attempts: list[Attempt] = []
    result = dict(request_id=str(uuid4()), kind=question.kind, attempts=attempts)
    for provider in self.providers:
        tick = perf_counter()
        if policy.local_only and provider.locality != "local":
            attempts.append(Attempt(provider=provider.name, outcome="blocked", latency_ms=0))
            continue
        try:
            raw = await asyncio.wait_for(provider.infer(question), policy.timeout_ms / 1000)
            try:
                probabilities = validate_probabilities(question, raw)
            except ValueError:
                outcome = "invalid_output"
            else:
                confidence = max(probabilities.values())
                if confidence >= policy.min_confidence:
                    attempts.append(Attempt(provider=provider.name, outcome="accepted", latency_ms=(perf_counter()-tick)*1000))
                    return Decision(**result, status="accepted", value=value_from(question, probabilities),
                                    probabilities=probabilities, confidence=confidence, provider=provider.name,
                                    model=provider.model, latency_ms=(perf_counter()-started)*1000)
                outcome = "low_confidence"
        except TimeoutError:
            outcome = "timeout"
        except Exception:
            # Deliberately omit provider exception text: it can contain inputs or credentials.
            outcome = "error"
        attempts.append(Attempt(provider=provider.name, outcome=outcome, latency_ms=(perf_counter()-tick)*1000))
    return Decision(**result, status="abstained", latency_ms=(perf_counter()-started)*1000)

def __init__(self, providers: list[Provider], policy: Policy | None = None):
    if not providers or len({p.name for p in providers}) != len(providers):
        raise ValueError("provide at least one provider with unique names")
    self.providers = tuple(providers)
    self.policy = policy or Policy()

def validate_cases(cases: list[Case]) -> None:
    """Reject mislabeled or malformed evaluation data before any provider runs."""
    if not cases or any(not isinstance(c.id, str) or not c.id.strip() for c in cases):
        raise ValueError("evaluation needs nonempty case IDs and cases")
    if len({c.id for c in cases}) != len(cases):
        raise ValueError("case IDs must be unique")
    for case in cases:
        question_adapter.validate_python(case.question.model_dump())
        if isinstance(case.question, Score):
            if (type(case.expected) not in (int, float) or not math.isfinite(case.expected)
                    or not 0 <= case.expected <= len(case.question.levels) - 1):
                raise ValueError("score labels must be finite numbers in the rubric range")
        elif case.question.kind == "predict":
            if type(case.expected) is not bool:
                raise ValueError("predicate labels must be booleans")
        elif type(case.expected) is not str or case.expected not in labels_for(case.question):
            raise ValueError("expected label is not in choices")

def value_from(question: Question, probabilities: dict[str, float]) -> str | bool | float:
    if isinstance(question, Predict):
        return probabilities["true"] >= 0.5
    if isinstance(question, Score):
        return sum(int(k) * p for k, p in probabilities.items())
    return max(probabilities, key=probabilities.__getitem__)

def validate_probabilities(question: Question, raw: object) -> dict[str, float]:
    if not isinstance(raw, dict) or set(raw) != set(labels_for(question)):
        raise ValueError("provider must return exactly the requested labels")
    if any(type(p) not in (int, float) or not math.isfinite(p) or not 0 <= p <= 1 for p in raw.values()):
        raise ValueError("probabilities must be finite numbers in [0,1]")
    if not math.isclose(sum(raw.values()), 1.0, abs_tol=1e-5):
        raise ValueError("probabilities must sum to one")
    return {label: float(raw[label]) for label in labels_for(question)}

@field_validator("options")
@classmethod
def exact_keys(cls, options: dict[str, str]) -> dict[str, str]:
    if any(not key.strip() or key != key.strip() for key in options):
        raise ValueError("option keys must not have surrounding whitespace")
    return {key: options[key] for key in _json_key_order(options)}

def labels_for(question: Question) -> list[str]:
    if isinstance(question, Choose):
        # Also cover model_copy/model_construct, which intentionally bypass Pydantic validators.
        return _json_key_order(question.options)
    if isinstance(question, Predict):
        return ["false", "true"]
    return [str(i) for i in range(len(question.levels))]
